import React from 'react';
import { NavLink } from 'react-router-dom';
import { LayoutDashboard, User, Send, Search, LogOut } from 'lucide-react';

const Sidebar = () => {
  const menuItems = [
    { path: '/student/dashboard', label: 'لوحة التحكم', icon: <LayoutDashboard size={22} /> },
    { path: '/student/search', label: 'استكشاف العروض', icon: <Search size={22} /> },
    { path: '/student/applications', label: 'طلباتي', icon: <Send size={22} /> },
    { path: '/student/profile', label: 'الملف الشخصي', icon: <User size={22} /> },
  ];

  return (
    <div className="w-64 h-screen bg-white border-l border-slate-100 flex flex-col p-6 fixed right-0 top-0" dir="rtl">
      {/* شعار المنصة */}
      <div className="text-2xl font-black text-blue-600 mb-10 px-4">
        Stag.io
      </div>

      {/* قائمة التنقل */}
      <nav className="flex-1 space-y-2">
        {menuItems.map((item) => (
          <NavLink
            key={item.path}
            to={item.path}
            
            className={({ isActive }) => 
             `w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${
                isActive 
                ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' 
                : 'text-slate-500 hover:bg-slate-50'
              }`
             }
          >
            {item.icon}
            <span>{item.label}</span>
          </NavLink>
        ))}
      </nav>

      {/* زر تسجيل الخروج */}
      <NavLink 
        to="/login" 
        className="flex items-center gap-3 px-4 py-3 text-red-500 font-bold hover:bg-red-50 rounded-xl transition-all mt-auto"
      >
        <LogOut size={22} />
        <span>تسجيل الخروج</span>
      </NavLink>
    </div>
  );
};

export default Sidebar;
